603	            throws Exception {
604	        mockMvc.perform(post("/api/batches/" + batchKey + "/recall")
605	                        .header("X-Actor-Id", actor)
606	                        .contentType(MediaType.APPLICATION_JSON)
607	                        .content("{\"commandKey\":\"" + commandKey + "\",\"reason\":\"" + reason
608	                                + "\"}"))
609	                .andExpect(status().is(expected));
