package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.util.List;

/**
 * 拆分请求体。父批由路径给出；children 为 2～5 个全新子批，各自提供全局唯一的
 * batchKey、批号 batchNo 与分摊数量 quantity（父批登记数量时必填，为正）。
 * 子批分摊数量之和必须严格等于父批操作时刻数量，否则 422 且整次回滚；
 * 子批键已存在或请求内重复时整次 409，父批不变。
 */
public record SplitRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "children 不能为空")
        @Size(min = 2, max = 5, message = "children 必须包含 2～5 个子批")
        List<@Valid ChildSpec> children
) {

    /**
     * 子批规格：batchKey 全局唯一，batchNo 为子批批号；产品编码、生产时间与必做检验项继承父批。
     * quantity 为子批分摊数量（无量纲，正数）；父批未登记数量时必须省略。
     */
    public record ChildSpec(
            @NotBlank(message = "子批 batchKey 不能为空") String batchKey,
            @NotBlank(message = "子批 batchNo 不能为空") String batchNo,
            BigDecimal quantity
    ) {
    }
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 拆分响应。父批状态落定 SPLIT；子批初始 QUARANTINED，继承父批产品编码、
 * 生产 UTC 时间与必做检验项，不继承检验或批准记录。splitAt 为 UTC instant 即固化计算时刻。
 * 每个子批以父批在 splitAt 的当前效价为初始效价建立效价模型 v1（锚点 splitAt），
 * 衰减率与最低放行阈值继承父批当前模型版本；父批未登记数量/效价时 potency 为 null。
 */
public record SplitResponse(
        String parentBatchKey,
        BatchStatus parentStatus,
        List<SplitChild> children,
        Instant splitAt
) {

    /**
     * 拆分产生的子批概要；potency 为该子批固化的效价模型 v1，未登记效价时为 null。
     */
    public record SplitChild(
            String batchKey,
            String batchNo,
            String productCode,
            Instant producedAt,
            BatchStatus status,
            List<String> requiredTests,
            BigDecimal quantity,
            PotencyView potency,
            Instant createdAt
    ) {
    }
}

