        assertEquals("2026-01-11T00:00:00Z", body.path("children").get(0).path("potency")
                .path("anchorAt").asText());
        assertEquals(60, jdbc.queryForObject(
                "SELECT quantity FROM batch_lineage WHERE parent_key = ? AND child_key = ?",
